# Simulate removal of the prebuilt biplot layer exports within a test
# environment. Constructors generated by `adapt_layer_to_biplot()` are already
# defined locally and are left intact; every other exported prebuilt layer is
# replaced by an error stub so accidental namespace fallback is caught.
shadow_prebuilt_layers <- function(env = rlang::caller_env()) {
  prebuilt <- grep(
    "^(stat|geom)_(rows|cols)_",
    getNamespaceExports("ordr"),
    value = TRUE
  )
  defined <- prebuilt[vapply(
    prebuilt,
    function(name) rlang::env_has(env, name),
    logical(1L)
  )]
  shadowed <- setdiff(prebuilt, defined)
  stubs <- lapply(shadowed, function(name) {
    force(name)
    function(...) {
      rlang::abort(paste0(
        "Prebuilt biplot layer `", name, "` must not be used; ",
        "use a layer generated by `adapt_layer_to_biplot()`."
      ))
    }
  })
  names(stubs) <- shadowed
  rlang::env_bind(env, !!!stubs)
  invisible(shadowed)
}
